from pathlib import Path
import base64,hashlib,zipfile,subprocess,sys
DATA=''
raw=base64.b64decode(DATA)
assert hashlib.sha256(raw).hexdigest()=='cbb17412a98a80616a0cb909a183fab2643ae72e4ee74370d711b7aeee9ce5fa'
r=Path(__file__).resolve().parent
p=r/'source.zip';p.write_bytes(raw)
with zipfile.ZipFile(p)as z:z.extractall(r/'source')
subprocess.run([sys.executable,str(r/'source/build_standalone.py')],check=True)
print('Open source/index.html. Tables and editable source are in source/. No PDF in this version.')
